<?php $sponsorships = DB::table('sponsorships')->get(); $nulls = ['sponsor_id' => 0, 'sponsorship_status_id' => 0, 'identity_number' => 0, 'orphan_name' => 0, 'id' => 0]; foreach($sponsorships as $s) { if($s->sponsor_id === null) $nulls['sponsor_id']++; if($s->sponsorship_status_id === null) $nulls['sponsorship_status_id']++; if($s->identity_number === null) $nulls['identity_number']++; if($s->orphan_name === null) $nulls['orphan_name']++; if($s->id === null) $nulls['id']++; } echo json_encode($nulls);
